WITH daily_brand AS ( SELECT cr.cr_returned_date_sk AS returned_date, i.i_brand AS brand, td.t_hour AS hour_of_day, SUM(cr.cr_net_loss) AS daily_brand_net_loss FROM catalog_returns cr JOIN item i ON cr.cr_item_sk = i.i_item_sk JOIN time_dim td ON cr.cr_returned_time_sk = td.t_time_sk GROUP BY cr.cr_returned_date_sk, i.i_brand, td.t_hour ) SELECT returned_date, brand, hour_of_day, daily_brand_net_loss, MAX(daily_brand_net_loss) OVER (PARTITION BY brand) AS max_brand_loss, CASE WHEN daily_brand_net_loss = MAX(daily_brand_net_loss) OVER (PARTITION BY brand) THEN 'Peak' ELSE 'Normal' END AS loss_indicator FROM daily_brand ORDER BY returned_date, brand, hour_of_day
